mapper.sql:
WHERE 1=1

    AND a.person_name LIKE CONCAT('%', #{personName}, '%')


    AND a.month = #{month}


    AND a.classes = #{classes}


    AND a.id_card = #{idCard}



    AND (o.office_name LIKE CONCAT('%', #{organization}, '%') OR backup_o.office_name LIKE CONCAT('%', #{organization}, '%'))


    AND (p.position_name LIKE CONCAT('%', #{workshop}, '%') OR backup_p.position_name LIKE CONCAT('%', #{workshop}, '%'))


    AND (fpl.prod_line_name LIKE CONCAT('%', #{process}, '%') OR backup_fpl.prod_line_name LIKE CONCAT('%', #{process}, '%'))


    AND (wg.work_group_name LIKE CONCAT('%', #{workGroupName}, '%') OR backup_wg.work_group_name LIKE CONCAT('%', #{workGroupName}, '%'))

mapper.select:
SELECT a.id, a.person_name AS "personName", a.month, a.classes, a.id_card AS "idCard", a.employee_id AS "employeeId", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks, a.status FROM swm_person_schedule a WHERE a.id_card = #{idCard}
AND a.month = #{month}
AND a.status = '0' AND (1=1 OR a.corp_code IS NOT NULL) ORDER BY a.update_date DESC

SELECT DISTINCT sp.identity_card AS "key", COALESCE(wg.work_group_name, backup_wg.work_group_name) AS "value" FROM swm_person sp -- 关联最新的 fms_worker 记录（使用 EXISTS 优化性能） LEFT JOIN fms_worker w ON sp.identity_card = w.identity_code COLLATE utf8mb4_general_ci AND NOT EXISTS ( SELECT 1 FROM fms_worker fw2 WHERE fw2.identity_code = w.identity_code AND fw2.create_date > w.create_date ) LEFT JOIN fms_work_group wg ON w.work_group_id = wg.id -- 备用关联（通过swm_person表中保存的team字段关联） LEFT JOIN fms_work_group backup_wg ON sp.team = backup_wg.id COLLATE utf8mb4_general_ci WHERE sp.identity_card IN
#{idCard}
AND sp.status = '0'

SELECT a.id AS "id", a.person_name AS "personName", a.month AS "month", a.classes AS "classes", a.id_card AS "idCard", a.employee_id AS "employeeId", jso.office_name AS "organization", pa.position_name AS "workshop", pl.prod_line_name AS "process", wg.work_group_name AS "workGroupName", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks", a.status AS "status" FROM swm_person_schedule a left join swm_person sp on a.id_card = sp.identity_card LEFT JOIN fms_position_archive pa ON sp.department = pa.id COLLATE utf8mb4_general_ci LEFT JOIN fms_prod_line pl ON sp.prod_line = pl.id COLLATE utf8mb4_general_ci LEFT JOIN fms_work_group wg ON sp.team = wg.id COLLATE utf8mb4_general_ci LEFT JOIN swm_work_type backup_wt ON sp.job_type = backup_wt.work_type_code COLLATE utf8mb4_general_ci LEFT JOIN js_sys_office jso ON sp.company = jso.office_code COLLATE utf8mb4_general_ci
a.status = '0' and sp.status = '0'
AND a.person_name LIKE CONCAT('%', #{personName}, '%')
AND a.month = #{month}
AND a.classes = #{classes}
AND a.id_card = #{idCard}
AND jso.office_name LIKE CONCAT('%', #{organization}, '%')
AND pa.position_name LIKE CONCAT('%', #{workshop}, '%')
AND pl.prod_line_name LIKE CONCAT('%', #{process}, '%')
AND wg.work_group_name LIKE CONCAT('%', #{workGroupName}, '%')
ORDER BY ${sqlMap.order.toSql()}

SELECT
a.id AS "id",
a.person_name AS "personName",
a.month AS "month",
a.id_card AS "idCard"
FROM swm_person_schedule a

    a.status = '0'

        AND a.month = #{month}


        AND a.corp_code = #{corpCode}


    AND #{random} = #{random}

ORDER BY ${sqlMap.order.toSql()}

SELECT a.id_card FROM swm_person_schedule a


        AND a.id IN

            #{id}
